-- Upload bookkeeping (#217, #21 part 3, docs/engineering/storage.md). One `blob` row per uploaded
-- object: createUploadIntent inserts it with scan_status null (open intent); finalizeUpload sets the
-- sniffed mime, sha256, finalized_at and scan_status 'pending' for the ClamAV worker. enc_header is
-- reserved for encrypted blob bodies (null today). Tenant table: ENABLE + FORCE RLS and
-- `ws_isolation` in this same migration. The key is globally unique (it embeds the workspace id).
CREATE TABLE "blob" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"key" text NOT NULL,
	"kind" text NOT NULL,
	"filename" text NOT NULL,
	"size" bigint NOT NULL,
	"sha256" text,
	"mime" text NOT NULL,
	"enc_header" "bytea",
	"scan_status" text,
	"created_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"finalized_at" timestamp with time zone,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "blob_scan_status_chk" CHECK ("blob"."scan_status" is null or "blob"."scan_status" in ('pending', 'clean', 'infected', 'skipped')),
	CONSTRAINT "blob_finalized_chk" CHECK (("blob"."finalized_at" is null) = ("blob"."scan_status" is null) and ("blob"."finalized_at" is null or "blob"."sha256" is not null))
);
